import { useEffect, useState } from 'react';
import axios from '../../api/axiosInstance';
import Sidebar from '../../components/Sidebar';
import Topbar from '../../components/Topbar';

const Card = ({ title, value, color }) => (
    <div className={`flex-1 p-6 rounded-xl text-white shadow-md`} style={{ backgroundColor: color }}>
        <div className="text-lg font-semibold">{title}</div>
        <div className="text-4xl font-bold mt-2">{value}</div>
    </div>
);

const Dashboard = () => {
    const [stats, setStats] = useState({ totalProjects: 0, totalEmployees: 0, totalMaterials: 0 });
    useEffect(() => {
        axios.get('/reports/admin').then(res => setStats(res.data));
    }, []);

    return (
        <div>
            <Sidebar />
            <Topbar />
            <div className="ml-[220px] p-6 mt-4 bg-gray-50 min-h-screen">
                <h2 className="text-3xl font-bold mb-6 text-gray-800">📊 Thống kê Tổng quan</h2>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                    <Card title="Tổng Dự Án" value={stats.totalProjects} color="#4CAF50" />
                    <Card title="Tổng Nhân Sự" value={stats.totalEmployees} color="#FF9800" />
                    <Card title="Tổng Vật Tư" value={stats.totalMaterials} color="#2196F3" />
                </div>
            </div>
        </div>
    );
};

export default Dashboard;
